def table(rows,widths=None,head=True,small=False):
 data=[[p(str(v),'SmallX' if small else 'CellX') for v in row] for row in rows]
 t=Table(data,colWidths=widths,hAlign='LEFT',repeatRows=1 if head else 0)
 t.setStyle(TableStyle([('FONTNAME',(0,0),(-1,-1),'Guide'),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5),('ROWBACKGROUNDS',(0,1 if head else 0),(-1,-1),[colors.white,colors.HexColor('#F5F7F8')]),('BACKGROUND',(0,0),(-1,0),LIGHT if head else colors.white),('LINEBELOW',(0,-1),(-1,-1),.5,colors.HexColor('#BDCED3'))]))
 S.append(t);S.append(Spacer(1,8))
def page():S.append(PageBreak())
def profiles(key):
 d=D[key];n=len(d['left']); rows=[['Circles: first to last','Squares: first to last']]
 for (a,x),(b,y) in zip(d['left'].items(),d['right'].items()):rows.append([a+': '+ ' > '.join(x),b+': '+' > '.join(y)])
 table(rows,[264,264])
def blockers_table(key,all_blockers=False):
 rows=[['Candidate pairing','Blocking pair(s), or stable']]
 for r in D[key]['candidates']:
  rows.append([r['matching'].replace('/',' / '),', '.join(r['blockers']) if all_blockers else (r['blockers'][0] if r['blockers'] else '<b>Stable</b>')])
 table(rows,[230,298])
class Matchings(Flowable):
 def __init__(self,matchings,left='AB',right='XY',titles=None,width=528,height=None,blocks=None):
  Flowable.__init__(self);self.ms=matchings;self.left=left;self.right=right;self.titles=titles or matchings;self.width=width;self.height=height or (45+len(left)*30);self.blocks=blocks or [None]*len(matchings)
 def draw(self):
  c=self.canv;span=self.width/len(self.ms)
  for k,code in enumerate(self.ms):
   x=k*span;lx=x+span*.25;rx=x+span*.75;top=self.height-38;step=min(29,(self.height-50)/max(1,len(self.left)-1))
   c.setFillColor(INK);c.setFont('Guide-Bold',9.2);c.drawCentredString(x+span/2,self.height-10,self.titles[k])
   m=dict(pair.split(':') if ':' in pair else tuple(pair) for pair in code.split('/'))
   c.setStrokeColor(INK);c.setLineWidth(1.1)
   for a,b in m.items():c.line(lx,top-self.left.index(a)*step,rx,top-self.right.index(b)*step)
   if self.blocks[k]:
    a,b=self.blocks[k];c.setStrokeColor(TEAL);c.setDash(3,2);c.setLineWidth(2);c.line(lx,top-self.left.index(a)*step,rx,top-self.right.index(b)*step);c.setDash()
   for i,a in enumerate(self.left):
    cy=top-i*step;c.setFillColor(colors.white);c.setStrokeColor(INK);c.circle(lx,cy,10,stroke=1,fill=1);c.setFillColor(INK);c.setFont('Guide-Bold',10);c.drawCentredString(lx,cy-3.3,a)
   for i,b in enumerate(self.right):
    cy=top-i*step;c.setFillColor(colors.white);c.setStrokeColor(INK);c.rect(rx-10,cy-10,20,20,stroke=1,fill=1);c.setFillColor(INK);c.drawCentredString(rx,cy-3.3,b)
  c.setStrokeColor(INK)
def diagram(*args,**kwargs):S.append(Matchings(*args,**kwargs));S.append(Spacer(1,5))

def footer(c,doc):
 c.saveState();c.setFillColor(GRAY);c.setFont('Guide',8.3)
